<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">H₀ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> transverse_field_ising</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FiniteChain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(L); g </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> g₀)</span></span>
